const userId = pm.collectionVariables.get("userId");
const userName = pm.collectionVariables.get("userName");
const userEmail = pm.collectionVariables.get("userEmail");

pm.variables.set("beforeUserId", userId);
pm.variables.set("beforeUserName", userName);
pm.variables.set("beforeUserEmail", userEmail);

pm.test("상태 코드 확인", function(){
    pm.response.to.have.status(200);
});

pm.test("json 타입 확인", function(){
    pm.response.to.be.json;
});

pm.test("데이터 배열 확인", function(){
    const data = pm.response.json();
    pm.expect(Array.isArray(data)).to.be.true;
});

pm.test("게시글 1개 이상인지 확인", function(){
    const data = pm.response.json();
    pm.expect(data.length).to.be.at.least(1);
});

pm.test("모든 게시글 id가 컬렉션 변수와 동일한지", function(){
    const data = pm.response.json();
    const expectedUserId = Number(pm.collectionVariables.get("userId"));

    data.forEach(function(post){
        pm.expect(post.userId).to.eql(expectedUserId);
    });
});

pm.test("모든 게시글 id가 양의 정수인지", function(){
    const data = pm.response.json();

    const ids = data.map(post => post.id);
    const validIds = ids.every(id => Number.isInteger(id) && id > 0);
    pm.expect(validIds).to.be.true;
});

pm.test("모든 게시글의 title이 비어있지 않은지", function(){
    const data = pm.response.json();

    data.forEach(function(post){
        pm.expect(post.title).to.be.a("string");
        pm.expect(post.title.trim()).to.not.be.empty;
    });
})
